echo 'add(){ echo $(( $1 - $2 )); }' > lib.sh; git add .; git commit -qm base
printf '@test "add" {
  . ./lib.sh
  [ "$(add 2 3)" = 5 ]
}
' > tests/add.bats; git add .; git commit -qm red; RED=$(git rev-parse HEAD)
printf '@test "add" {
  true
}
' > tests/add.bats; echo '# touched' >> lib.sh; git commit -qam "fix (weakens test)"
bash $S --red $RED --test-file tests/add.bats -- bats tests/add.bats; echo rc=$?

